<section class="card"><div class="card-head"><div><h2><?= $edit?'Edit Penyaluran':'Catat Penyaluran Dana' ?></h2><p class="muted">Ketik nama mustahik/penerima. Jika belum terdaftar, data baru otomatis dibuat. Jurnal kas ikut diperbarui.</p></div><?php if($edit):?><a class="btn btn-ghost" href="index.php?page=penyaluran">Batal edit</a><?php endif;?></div><?php if($err):?><div class="alert alert-err"><?=e($err)?></div><?php endif;?>
<form method="POST" class="form-grid"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif;?>
<label>Tanggal penyaluran<input type="date" name="tanggal" value="<?=e($edit['tanggal']??$_POST['tanggal']??date('Y-m-d'))?>" required></label><label>Nama Mustahik / Penerima<input type="text" name="nama_mustahik" maxlength="100" placeholder="Ketik nama penerima dana" value="<?=e($_POST['nama_mustahik']??$edit['mustahik']??'')?>" required></label>
<label>Asnaf / Jenis penerima<select name="asnaf" required><?php foreach($asnaf as $a):?><option value="<?=e($a['nama'])?>" <?=((($_POST['asnaf']??$edit['asnaf']??'Fakir')===$a['nama'])?'selected':'')?>><?=e($a['nama'])?></option><?php endforeach;?></select></label><label>Pos dana<select name="pos_dana" required><option value="">Pilih pos dana</option><?php foreach(JurnalKas::POS as $key=>$nama):?><option value="<?=e($key)?>" <?=((($_POST['pos_dana']??$edit['pos_dana']??'')===$key)?'selected':'')?>><?=e($nama)?></option><?php endforeach;?></select></label><label>Nominal (Rp)<input type="number" name="nominal" min="1" step="1" value="<?=e($_POST['nominal']??$edit['nominal']??'')?>" required></label><label class="full">Keterangan<input name="keterangan" maxlength="255" value="<?=e($_POST['keterangan']??$edit['keterangan']??'')?>" placeholder="Contoh: Bantuan kebutuhan pokok"></label><div class="full"><button class="btn btn-primary" type="submit"><?=$edit?'Simpan Perubahan':'Simpan Penyaluran + Jurnal'?></button></div></form></section>
<section class="card"><h2>Riwayat Penyaluran</h2><div class="table-wrap"><table><thead><tr><th>No Bukti</th><th>Tanggal</th><th>Mustahik/Penerima</th><th>Asnaf</th><th>Pos Dana</th><th>Nominal</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">Belum ada penyaluran.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['no_bukti'])?></td><td><?=e(tgl($r['tanggal']))?></td><td><?=e($r['mustahik'])?></td><td><?=e($r['asnaf'])?></td><td><?=e(JurnalKas::POS[$r['pos_dana']]??$r['pos_dana'])?></td><td class="num"><?=rupiah($r['nominal'])?></td><td class="actions"><a class="btn btn-sm btn-warn" href="index.php?page=penyaluran&action=edit&id=<?=(int)$r['id']?>">Edit</a><form method="POST" data-confirm="Hapus penyaluran dan jurnal terkait?"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section>
